        private async Task ComboMethodICD()
        {
            try
            {
                this.autoCheckIcd = HIS.Desktop.LocalStorage.HisConfig.HisConfigs.Get<long>("HIS.Desktop.Plugins.AutoCheckIcd");
                chkIcd1.Enabled = (this.autoCheckIcd != 2);
                chkIcd2.Enabled = (this.autoCheckIcd != 2);
                chkIcd3.Enabled = (this.autoCheckIcd != 2);
                chkIcdCm.Enabled = (this.autoCheckIcd != 2);
                List<HIS_ICD> datas = null;
                if (BackendDataWorker.IsExistsKey<HIS_ICD>())
                {
                    datas = HIS.Desktop.LocalStorage.BackendData.BackendDataWorker.Get<HIS_ICD>();
                }
                else
                {
                    CommonParam paramCommon = new CommonParam();
                    dynamic filter = new System.Dynamic.ExpandoObject();
                    datas = await new Inventec.Common.Adapter.BackendAdapter(paramCommon).GetAsync<List<HIS_ICD>>("api/HisIcd/Get", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, filter, paramCommon);
                    if (datas != null) BackendDataWorker.UpdateToRam(typeof(HIS_ICD), datas, long.Parse(DateTime.Now.ToString("yyyyMMddHHmmss")));
                }

                this.dataIcds = new List<HIS_ICD>();
                if (datas != null && datas.Count > 0)
                    this.dataIcds = datas.Where(p => p.IS_ACTIVE == IMSys.DbConfig.HIS_RS.COMMON.IS_ACTIVE__TRUE).ToList();

                DataToComboChuanDoanTD(cboIcd1);
                DataToComboChuanDoanTD(cboIcd2);
                DataToComboChuanDoanTD(cboIcd3);

                List<HIS_ICD_CM> dataCms = null;
                if (BackendDataWorker.IsExistsKey<HIS_ICD_CM>())
                {
                    dataCms = HIS.Desktop.LocalStorage.BackendData.BackendDataWorker.Get<HIS_ICD_CM>();
                }
                else
                {
                    CommonParam paramCommon = new CommonParam();
                    dynamic filter = new System.Dynamic.ExpandoObject();
                    dataCms = await new Inventec.Common.Adapter.BackendAdapter(paramCommon).GetAsync<List<HIS_ICD_CM>>("api/HisIcdCm/Get", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, filter, paramCommon);
                    if (dataCms != null) BackendDataWorker.UpdateToRam(typeof(HIS_ICD_CM), dataCms, long.Parse(DateTime.Now.ToString("yyyyMMddHHmmss")));
                }

                this.dataIcdCms = new List<HIS_ICD_CM>();
                if (dataCms != null && dataCms.Count > 0)
                    this.dataIcdCms = dataCms.Where(p => p.IS_ACTIVE == IMSys.DbConfig.HIS_RS.COMMON.IS_ACTIVE__TRUE).ToList();

                DataToComboChuanDoanTD(cboIcdCmName, true);
            }
            catch (Exception ex)
            {
                Inventec.Common.Logging.LogSystem.Warn(ex);
            }
        }

        private void DataToComboChuanDoanTD(CustomGridLookUpEditWithFilterMultiColumn cbo, bool isIcdCM = false)
        {
            try
            {
                List<IcdADO> list = new List<IcdADO>();
                if (isIcdCM)
                {
                    foreach (HIS_ICD_CM dataIcdCm in dataIcdCms)
                    {
                        IcdADO icdADO = new IcdADO();
                        ((HIS_ICD)icdADO).ID = dataIcdCm.ID;
                        ((HIS_ICD)icdADO).ICD_CODE = dataIcdCm.ICD_CM_CODE;
                        ((HIS_ICD)icdADO).ICD_NAME = dataIcdCm.ICD_CM_NAME;
                        icdADO.ICD_NAME_UNSIGN = convertToUnSign3(dataIcdCm.ICD_CM_NAME);
                        list.Add(icdADO);
                    }
                }
                else
                {
                    foreach (HIS_ICD dataIcd in dataIcds)
                    {
                        IcdADO icdADO2 = new IcdADO();
                        ((HIS_ICD)icdADO2).ID = dataIcd.ID;
                        ((HIS_ICD)icdADO2).ICD_CODE = dataIcd.ICD_CODE;
                        ((HIS_ICD)icdADO2).ICD_NAME = dataIcd.ICD_NAME;
                        icdADO2.ICD_NAME_UNSIGN = convertToUnSign3(dataIcd.ICD_NAME);
                        list.Add(icdADO2);
                    }
                }
                ((RepositoryItemLookUpEditBase)(object)cbo.Properties).DataSource = list;
                ((RepositoryItemLookUpEditBase)(object)cbo.Properties).DisplayMember = "ICD_NAME";
                ((RepositoryItemLookUpEditBase)(object)cbo.Properties).ValueMember = "ID";
                ((RepositoryItemButtonEdit)(object)cbo.Properties).TextEditStyle = TextEditStyles.Standard;
                ((RepositoryItemGridLookUpEditBase)(object)cbo.Properties).PopupFilterMode = PopupFilterMode.Contains;
                ((RepositoryItemPopupBaseAutoSearchEdit)(object)cbo.Properties).ImmediatePopup = true;
                ((GridLookUpEditBase)(object)cbo).ForceInitialize();
                ((RepositoryItemGridLookUpEditBase)(object)cbo.Properties).View.Columns.Clear();
                ((RepositoryItemPopupBase)(object)cbo.Properties).PopupFormSize = new Size(900, 250);
                GridColumn gridColumn = ((RepositoryItemGridLookUpEditBase)(object)cbo.Properties).View.Columns.AddField("ICD_CODE");
                gridColumn.Caption = "Mã";
                gridColumn.Visible = true;
                gridColumn.VisibleIndex = 1;
                gridColumn.Width = 60;
                GridColumn gridColumn2 = ((RepositoryItemGridLookUpEditBase)(object)cbo.Properties).View.Columns.AddField("ICD_NAME");
                gridColumn2.Caption = "Tên";
                gridColumn2.Visible = true;
                gridColumn2.VisibleIndex = 2;
                gridColumn2.Width = 340;
                GridColumn gridColumn3 = ((RepositoryItemGridLookUpEditBase)(object)cbo.Properties).View.Columns.AddField("ICD_NAME_UNSIGN");
                gridColumn3.Visible = true;
                gridColumn3.VisibleIndex = -1;
                gridColumn3.Width = 340;
                ((RepositoryItemGridLookUpEditBase)(object)cbo.Properties).View.Columns["ICD_NAME_UNSIGN"].Width = 0;
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
            }
        }

        private string convertToUnSign3(string s)
        {
            Regex regex = new Regex("\\p{IsCombiningDiacriticalMarks}+");
            string input = s.Normalize(NormalizationForm.FormD);
            return regex.Replace(input, string.Empty).Replace('đ', 'd').Replace('Đ', 'D');
        }

        private void FillDataToCboIcd(TextEdit txtIcdCode, TextEdit txtIcdMain, CustomGridLookUpEditWithFilterMultiColumn cbo, CheckEdit chkEdit, string _ICD_CODE, string _ICD_NAME)
        {
            try
            {
                if (string.IsNullOrEmpty(_ICD_CODE))
                {
                    return;
                }
                HIS_ICD val = dataIcds.Where((HIS_ICD p) => p.ICD_CODE == _ICD_CODE).FirstOrDefault();
                if (val != null)
                {
                    txtIcdCode.Text = val.ICD_CODE;
                    ((BaseEdit)(object)cbo).EditValue = val.ID;
                    if (autoCheckIcd == 1 || (!string.IsNullOrEmpty(_ICD_NAME) && (_ICD_NAME ?? "").Trim().ToLower() != (val.ICD_NAME ?? "").Trim().ToLower()))
                    {
                        chkEdit.Checked = autoCheckIcd != 2;
                        txtIcdMain.Text = _ICD_NAME;
                    }
                    else
                    {
                        chkEdit.Checked = false;
                        txtIcdMain.Text = val.ICD_NAME;
                    }
                }
            }
            catch (Exception ex)
            {
                LogSystem.Error(ex);
            }
        }

