        internal void LoadIcdCombo(string searchCode, TextEdit txtIcdCode, TextEdit txtIcdMain, CustomGridLookUpEditWithFilterMultiColumn cbo, CheckEdit chkEdit)
        {
            try
            {
                bool flag = true;
                if (!string.IsNullOrEmpty(searchCode))
                {
                    List<HIS_ICD> list = dataIcds.Where((HIS_ICD o) => o.ICD_CODE.Contains(searchCode)).ToList();
                    List<HIS_ICD> list2 = ((list == null) ? null : ((list.Count > 1) ? list.Where((HIS_ICD o) => o.ICD_CODE == searchCode).ToList() : list));
                    if (list2 != null && list2.Count > 0)
                    {
                        flag = false;
                        txtIcdCode.Text = list2.First().ICD_CODE;
                        txtIcdMain.Text = list2.First().ICD_NAME;
                        ((BaseEdit)(object)cbo).EditValue = list.First().ID;
                        chkEdit.Checked = chkEdit.Enabled && autoCheckIcd == 1;
                        if (chkEdit.Checked)
                        {
                            txtIcdMain.Focus();
                            txtIcdMain.SelectAll();
                        }
                        else
                        {
                            ((Control)(object)cbo).Focus();
                            ((BaseEdit)(object)cbo).SelectAll();
                        }
                    }
                }
                if (flag)
                {
                    ((Control)(object)cbo).Focus();
                    ((PopupBaseEdit)(object)cbo).ShowPopup();
                }
            }
            catch (Exception ex)
            {
                LogSystem.Error(ex);
            }
        }

