        public void ValidationICD(int? maxLengthCode, int? maxLengthText, bool isRequired, TextEdit txtIcdCode, TextEdit txtIcdMain, CustomGridLookUpEditWithFilterMultiColumn cbo, CheckEdit chkEdit, LayoutControlItem lciIcdText)
        {
            try
            {
                if (isRequired)
                {
                    lciIcdText.AppearanceItemCaption.ForeColor = Color.Maroon;
                    ICDValidationRuleControl iCDValidationRuleControl = new ICDValidationRuleControl();
                    iCDValidationRuleControl.txtIcdCode = txtIcdCode;
                    iCDValidationRuleControl.btnBenhChinh = (GridLookUpEdit)(object)cbo;
                    iCDValidationRuleControl.txtMainText = txtIcdMain;
                    iCDValidationRuleControl.chkCheck = chkEdit;
                    iCDValidationRuleControl.maxLengthCode = maxLengthCode;
                    iCDValidationRuleControl.maxLengthText = maxLengthText;
                    iCDValidationRuleControl.ErrorText = ResourceMessage.TruongDuLieuBatBuoc;
                    iCDValidationRuleControl.ErrorType = ErrorType.Warning;
                    dxValidationProvider1.SetValidationRule(txtIcdCode, iCDValidationRuleControl);
                }
                else
                {
                    lciIcdText.AppearanceItemCaption.ForeColor = default(Color);
                    txtIcdCode.ErrorText = "";
                    dxValidationProvider1.RemoveControlError(txtIcdCode);
                    dxValidationProvider1.SetValidationRule(txtIcdCode, null);
                }
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
            }
        }

        private void ChangecboChanDoanTD(TextEdit txtIcdCode, TextEdit txtIcdMain, CustomGridLookUpEditWithFilterMultiColumn cbo, CheckEdit chkEdit, TextEdit nextFocus)
        {
            try
            {
                ((RepositoryItemButtonEdit)(object)cbo.Properties).Buttons[1].Visible = true;
                HIS_ICD val = dataIcds.FirstOrDefault((HIS_ICD o) => o.ID == Parse.ToInt64((((BaseEdit)(object)cbo).EditValue ?? ((object)0)).ToString()));
                if (val != null)
                {
                    txtIcdCode.Text = val.ICD_CODE;
                    txtIcdMain.Text = val.ICD_NAME;
                    chkEdit.Checked = chkEdit.Enabled && autoCheckIcd == 1;
                    if (chkEdit.Checked && nextFocus != null)
                    {
                        nextFocus.Focus();
                        nextFocus.SelectAll();
                    }
                    else if (chkEdit.Enabled)
                    {
