        private void ChangecboIcdCmTD(TextEdit txtIcdCode, TextEdit txtIcdMain, CustomGridLookUpEditWithFilterMultiColumn cbo, CheckEdit chkEdit, TextEdit nextFocus)
        {
            try
            {
                ((RepositoryItemButtonEdit)(object)cbo.Properties).Buttons[1].Visible = true;
                HIS_ICD_CM val = dataIcdCms.FirstOrDefault((HIS_ICD_CM o) => o.ID == Parse.ToInt64((((BaseEdit)(object)cbo).EditValue ?? ((object)0)).ToString()));
                if (val != null)
                {
                    txtIcdCode.Text = val.ICD_CM_CODE;
                    txtIcdMain.Text = val.ICD_CM_NAME;
                    chkEdit.Checked = chkEdit.Enabled && autoCheckIcd == 1;
                    if (chkEdit.Checked && nextFocus != null)
                    {
                        nextFocus.Focus();
                        nextFocus.SelectAll();
                    }
                    else if (chkEdit.Enabled)
                    {
                        chkEdit.Focus();
                    }
                    else if (nextFocus != null)
                    {
                        nextFocus.Focus();
                        nextFocus.SelectAll();
                    }
                }
            }
            catch (Exception ex)
            {
                LogSystem.Error(ex);
            }
        }

