                                                      where o.IS_ACTIVE == 1
                                                      select o;
                foreach (V_HIS_EMPLOYEE item in acsUser)
                {
                    AcsUserADO ado = new AcsUserADO(item)
                    {
                        DOB = item.DOB.GetValueOrDefault().ToString(),
                        DOB_STR = Inventec.Common.DateTime.Convert.TimeNumberToDateString(item.DOB.GetValueOrDefault()),
                        DIPLOMA = item.DIPLOMA,
                        DEPARTMENT_CODE = item.DEPARTMENT_CODE,
                        DEPARTMENT_ID = item.DEPARTMENT_ID,
                        DEPARTMENT_NAME = item.DEPARTMENT_NAME
                    };
                    ((ACS_USER)ado).USERNAME = item.TDL_USERNAME;
