                ControlEditorLoader.Load((object)cboEndDeptSubs, (object)lstReAcsUserADO.Where((AcsUserADO o) => ((ACS_USER)o).IS_ACTIVE == 1).ToList(), controlEditorADO);
                ((RepositoryItemPopupBaseAutoSearchEdit)(object)cboEndDeptSubs.Properties).ImmediatePopup = true;
                ControlEditorLoader.Load((object)cboHospSubs, (object)lstReAcsUserADO.Where((AcsUserADO o) => ((ACS_USER)o).IS_ACTIVE == 1).ToList(), controlEditorADO);
                ((RepositoryItemPopupBaseAutoSearchEdit)(object)cboHospSubs.Properties).ImmediatePopup = true;
            }
            catch (Exception ex)
            {
                Exception ex2 = ex;
                LogSystem.Warn(ex2);
            }
        }

        private void ValidHeadDepartmentAndDirectorBranch()
        {
            try
            {
                V_HIS_ROOM RoomV = BackendDataWorker.Get<V_HIS_ROOM>().FirstOrDefault((V_HIS_ROOM o) => o.ID == this.Module.RoomId);
                HIS_DEPARTMENT Department = BackendDataWorker.Get<HIS_DEPARTMENT>().FirstOrDefault((HIS_DEPARTMENT o) => o.ID == RoomV.DEPARTMENT_ID);
                V_HIS_EMPLOYEE val = BackendDataWorker.Get<V_HIS_EMPLOYEE>().FirstOrDefault((V_HIS_EMPLOYEE o) => o.LOGINNAME == Department.HEAD_LOGINNAME);
                if (val != null && val.IS_NEED_SIGN_INSTEAD == 1)
                {
                    ValidationSigleControl((BaseEdit)(object)cboEndDeptSubs);
                    lciEndDeptSubs.AppearanceItemCaption.ForeColor = Color.Maroon;
                }
                else
                {
                    dxValidationProvider1.RemoveControlError((Control)(object)cboEndDeptSubs);
                    dxValidationProvider1.SetValidationRule((Control)(object)cboEndDeptSubs, null);
                    lciEndDeptSubs.AppearanceItemCaption.ForeColor = Color.Black;
                }
                HIS_BRANCH Branch = BackendDataWorker.Get<HIS_BRANCH>().FirstOrDefault((HIS_BRANCH o) => o.ID == Department.BRANCH_ID);
                V_HIS_EMPLOYEE val2 = BackendDataWorker.Get<V_HIS_EMPLOYEE>().FirstOrDefault((V_HIS_EMPLOYEE o) => o.LOGINNAME == Branch.DIRECTOR_LOGINNAME);
                if (val2 != null && val2.IS_NEED_SIGN_INSTEAD == 1)
                {
                    ValidationSigleControl((BaseEdit)(object)cboHospSubs);
                    lciHospSubs.AppearanceItemCaption.ForeColor = Color.Maroon;
                }
                else
                {
                    dxValidationProvider1.RemoveControlError((Control)(object)cboHospSubs);
                    dxValidationProvider1.SetValidationRule((Control)(object)cboHospSubs, null);
                    lciHospSubs.AppearanceItemCaption.ForeColor = Color.Black;
                }
            }
            catch (Exception ex)
            {
                LogSystem.Error(ex);
            }
        }

