        private async void LoadDataSesePtttMethodDetail(List<HIS_SESE_PTTT_METHOD> listMethod)
        {
            try
            {
                if (listMethod == null || listMethod.Count <= 0)
                {
                    return;
                }
                List<PtttMethodADO> oldData = listSesePtttMetod.Where((PtttMethodADO o) => listMethod.Select((HIS_SESE_PTTT_METHOD s) => s.TDL_SERE_SERV_ID).Contains(o.SERE_SERV_ID)).ToList();
                if (oldData != null && oldData.Count > 0)
                {
                    listSesePtttMetod = listSesePtttMetod.Where((PtttMethodADO o) => !oldData.Select((PtttMethodADO s) => s.ID).Contains(o.ID)).ToList();
                }
                List<long> listEkipId = listMethod.Select((HIS_SESE_PTTT_METHOD s) => s.EKIP_ID.GetValueOrDefault()).Distinct().ToList();
                CommonParam param = new CommonParam();
                List<HIS_EKIP_USER> ekipUser = new List<HIS_EKIP_USER>();
                if (listEkipId.Count > 0)
                {
                    HisEkipUserFilter userFilter = new HisEkipUserFilter();
                    userFilter.EKIP_IDs = listEkipId;
                    ekipUser = ((AdapterBase)new BackendAdapter(param)).Get<List<HIS_EKIP_USER>>("api/HisEkipUser/Get", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, (object)userFilter, param);
                }
                foreach (HIS_SESE_PTTT_METHOD item in listMethod)
                {
                    PtttMethodADO ado = new PtttMethodADO
                    {
                        ID = item.PTTT_METHOD_ID,
                        AMOUNT = item.AMOUNT,
                        PTTT_GROUP_ID = item.PTTT_GROUP_ID,
                        SERE_SERV_ID = item.TDL_SERE_SERV_ID,
                        EKIP_ID = item.EKIP_ID,
                        SERVICE_REQ_ID = item.TDL_SERVICE_REQ_ID
                    };
                    if (item.EKIP_ID.HasValue)
                    {
                        ado.EkipUsersADO = new EkipUsersADO();
                        List<HIS_EKIP_USER> kips = ekipUser.Where((HIS_EKIP_USER o) => o.EKIP_ID == item.EKIP_ID).ToList();
                        List<HisEkipUserADO> lst = new List<HisEkipUserADO>();
                        for (int i = 0; i < kips.Count; i++)
                        {
                            HisEkipUserADO Ekipado = new HisEkipUserADO();
                            ((V_HIS_EKIP_USER)Ekipado).USERNAME = kips[i].USERNAME;
                            ((V_HIS_EKIP_USER)Ekipado).LOGINNAME = kips[i].LOGINNAME;
                            ((V_HIS_EKIP_USER)Ekipado).EXECUTE_ROLE_ID = kips[i].EXECUTE_ROLE_ID;
                            lst.Add(Ekipado);
                        }
                        ado.EkipUsersADO.idPtttMethod = item.PTTT_METHOD_ID;
                        ado.EkipUsersADO.listEkipUser = lst;
                    }
                    HIS_PTTT_METHOD method = BackendDataWorker.Get<HIS_PTTT_METHOD>().FirstOrDefault((HIS_PTTT_METHOD o) => o.ID == item.PTTT_METHOD_ID);
                    if (method != null)
                    {
                        ado.PTTT_METHOD_CODE = method.PTTT_METHOD_CODE;
                        ado.PTTT_METHOD_NAME = method.PTTT_METHOD_NAME;
                    }
                    listSesePtttMetod.Add(ado);
                }
            }
            catch (Exception ex)
            {
                Exception ex2 = ex;
                LogSystem.Error(ex2);
            }
        }

