        private void createTabPage(List<PtttMethodADO> lstData)
        {
            //IL_010e: Unknown result type (might be due to invalid IL or missing references)
            //IL_0115: Expected O, but got Unknown
            try
            {
                foreach (PtttMethodADO lstDatum in lstData)
                {
                    if (lstDatum.EkipUsersADO == null || lstDatum.EkipUsersADO.listEkipUser == null || lstDatum.EkipUsersADO.listEkipUser.Count <= 0)
                    {
                        continue;
                    }
                    EkipUsersADO ekipUsersADO = new EkipUsersADO();
                    PanelControl panelControl = new PanelControl();
                    panelControl.Dock = DockStyle.Fill;
                    panelControl.Name = "panel_" + lstDatum.ID;
                    XtraTabPage xtraTabPage = new XtraTabPage();
                    xtraTabPage.Controls.Add(panelControl);
                    xtraTabPage.Text = lstDatum.PTTT_METHOD_NAME;
                    xtraTabPage.Name = lstDatum.ID.ToString();
                    xtraTabControl2.TabPages.Add(xtraTabPage);
                    UCEkipUser uCEkipUser = new UCEkipUser();
                    panelControl.Controls.Add((Control)(object)uCEkipUser);
                    ((Control)(object)uCEkipUser).Dock = DockStyle.Fill;
                    foreach (HisEkipUserADO item in lstDatum.EkipUsersADO.listEkipUser)
                    {
                        HisEkipUserADO val = new HisEkipUserADO();
                        DataObjectMapper.Map<HisEkipUserADO>((object)val, (object)item);
                        lstAllEkip.Add(val);
                    }
                    uCEkipUser.FillDataToGrid(lstDatum.EkipUsersADO.listEkipUser);
                    uCEkipUser.FillDataToInformationSurg(false);
                }
            }
            catch (Exception ex)
            {
                LogSystem.Error(ex);
            }
        }

        private async void ProcessLoadRealPtttMethod(V_HIS_SERE_SERV_PTTT dataPttt)
        {
            try
            {
                layoutControlItem25.Visibility = LayoutVisibility.Always;
                txtPhuongPhapTT.Text = "";
                cboPhuongPhapThucTe.EditValue = null;
                if (dataPttt == null)
                {
                    return;
                }
                if (dataPttt.REAL_PTTT_METHOD_ID > 0)
                {
                    HIS_PTTT_METHOD data = BackendDataWorker.Get<HIS_PTTT_METHOD>().FirstOrDefault((HIS_PTTT_METHOD p) => p.ID == dataPttt.REAL_PTTT_METHOD_ID);
                    if (data != null)
                    {
                        txtPhuongPhapTT.Text = data.PTTT_METHOD_CODE;
                        cboPhuongPhapThucTe.EditValue = data.ID;
                    }
                }
                else
                {
                    if (!listSesePtttMetod.Exists((PtttMethodADO o) => o.SERE_SERV_ID == dataPttt.SERE_SERV_ID))
                    {
                        return;
                    }
                    layoutControlItem25.Visibility = LayoutVisibility.Never;
                    List<string> pp = new List<string>();
                    List<PtttMethodADO> lstPtttMethod = listSesePtttMetod.Where((PtttMethodADO o) => o.SERE_SERV_ID == dataPttt.SERE_SERV_ID).ToList();
                    if (lstPtttMethod != null && lstPtttMethod.Count > 0)
                    {
                        foreach (PtttMethodADO item in lstPtttMethod)
                        {
                            pp.Add(string.Format("{0} - {1}", item.PTTT_METHOD_NAME, item.AMOUNT));
                        }
                    }
                    txtPhuongPhapTT.Text = string.Join("; ", pp);
                    if (IsChoosePTTT)
                    {
                        clearTabpage();
                    }
                    createTabPage(lstPtttMethod);
                    if (IsChoosePTTT)
                    {
                        ucEkip.FillDataToGrid(lstAllEkip);
                    }
                    ucEkip.FillDataToInformationSurg(false);
                }
            }
            catch (Exception ex)
            {
                Exception ex2 = ex;
                LogSystem.Error(ex2);
            }
        }

