        private dynamic TypeRequiredEmotionlessMethodOption(V_HIS_SERE_SERV_5 ss)
        {
            dynamic val = new ExpandoObject();
            val.RequiredEmotionlessOption = null;
            val.IsServiceTypePT = false;
            val.IsServiceTypeTT = false;
            try
            {
                if (HisConfigCFG.RequiredEmotionlessMethodOption == "1")
                {
                    val.RequiredEmotionlessOption = 1;
                    val.IsServiceTypePT = ss.TDL_SERVICE_TYPE_ID == 11;
                }
                else if (HisConfigCFG.RequiredEmotionlessMethodOption == "2")
                {
                    val.RequiredEmotionlessOption = 2;
                    if (ss.TDL_SERVICE_TYPE_ID == 11)
                    {
                        val.IsServiceTypePT = true;
                    }
                    else if (ss.TDL_SERVICE_TYPE_ID == 4)
                    {
                        val.IsServiceTypeTT = true;
                    }
                }
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
            }
            return val;
        }

        private void InValid()
        {
            //IL_01c4: Unknown result type (might be due to invalid IL or missing references)
            //IL_01ce: Expected O, but got Unknown
            try
            {
                Color foreColor = lciStartTime.AppearanceItemCaption.ForeColor;
                if (dtStart.ReadOnly)
                {
                    lciStartTime.AppearanceItemCaption.ForeColor = Color.Black;
                    dxValidationProvider1.SetValidationRule(dtStart, null);
                }
                else
                {
                    lciStartTime.AppearanceItemCaption.ForeColor = foreColor;
                    ValidationStartTime();
                }
                Color foreColor2 = layoutControlItem17.AppearanceItemCaption.ForeColor;
                if (txtLoaiPT.ReadOnly)
                {
                    layoutControlItem17.AppearanceItemCaption.ForeColor = Color.Black;
                    dxValidationProvider1.SetValidationRule(txtLoaiPT, null);
                }
                else
                {
                    layoutControlItem17.AppearanceItemCaption.ForeColor = foreColor2;
                    if (PriorityIsRequired == 1 || (PriorityIsRequired == 2 && serviceReq.SERVICE_REQ_TYPE_ID == 10))
                    {
                        ValidationGridLookUpWithTextEdit(cboLoaiPT, txtLoaiPT);
                    }
                }
                Color foreColor3 = lciKetLuan.AppearanceItemCaption.ForeColor;
                Color foreColor4 = lciPhanLoai.AppearanceItemCaption.ForeColor;
                if (txtPtttGroupCode.ReadOnly)
                {
                    lciPhanLoai.AppearanceItemCaption.ForeColor = Color.Black;
                    dxValidationProvider1.SetValidationRule(txtPtttGroupCode, null);
                    return;
                }
                lciPhanLoai.AppearanceItemCaption.ForeColor = Color.Black;
                dxValidationProvider1.SetValidationRule(txtPtttGroupCode, null);
                if (HisConfigCFG.REQUIRED_GROUPPTTT_OPTION != "1")
                {
                    sereServ = (V_HIS_SERE_SERV_5)grdViewService.GetFocusedRow();
                    V_HIS_SERE_SERV_5 obj = sereServ;
                    LogSystem.Debug("sereServValidate " + ((obj != null) ? ((object)obj).ToString() : null));
                    if (sereServ != null)
                    {
                        V_HIS_SERVICE val = lstService.FirstOrDefault((V_HIS_SERVICE o) => o.ID == sereServ.SERVICE_ID);
                        if (val != null && val != null && val.PTTT_GROUP_ID.HasValue)
                        {
                            lciPhanLoai.AppearanceItemCaption.ForeColor = foreColor4;
                            ValidationLookUpWithTextEdit(cbbPtttGroup, txtPtttGroupCode);
                        }
                    }
                }
                else
                {
                    lciPhanLoai.AppearanceItemCaption.ForeColor = foreColor4;
                    ValidationLookUpWithTextEdit(cbbPtttGroup, txtPtttGroupCode);
                }
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
            }
        }

