        private void btnDVPhatSinh_Click(object sender, EventArgs e)
        {
            try
            {
                IsActionOtherButton = true;
                if (!btnSaveClick(true))
                {
                    return;
                }
                Inventec.Desktop.Common.Modules.Module val = GlobalVariables.currentModuleRaws.Where((Inventec.Desktop.Common.Modules.Module o) => o.ModuleLink == "HIS.Desktop.Plugins.AssignPaan").FirstOrDefault();
                if (val == null)
                {
                    LogSystem.Error("khong tim thay moduleLink = HIS.Desktop.Plugins.AssignPaan");
                }
                if (val.IsPlugin && val.ExtensionInfo != null)
                {
                    List<object> list = new List<object>();
                    list.Add(serviceReq);
                    list.Add(sereServ);
                    list.Add(serviceReq.TREATMENT_ID);
                    list.Add(PluginInstance.GetModuleWithWorkingRoom(val, val.RoomId, val.RoomTypeId));
                    object pluginInstance = PluginInstance.GetPluginInstance(PluginInstance.GetModuleWithWorkingRoom(val, val.RoomId, val.RoomTypeId), list);
                    if (pluginInstance == null)
                    {
                        throw new ArgumentNullException("moduleData is null");
                    }
                    ((Form)pluginInstance).ShowDialog();
                }
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
            }
        }

