        private void CreateThreadLoadDataForService(ThreadChiDinhDichVuADO data)
        {
            Thread thread = new Thread(LoadDataTreatment);
            Thread thread2 = new Thread(LoadDataSereServ);
            Thread thread3 = new Thread(LoadDataSereServBill);
            Thread thread4 = new Thread(LoadDataSereServDeposit);
            try
            {
                thread.Start(data);
                thread2.Start(data);
                thread3.Start(data);
                thread4.Start(data);
                thread.Join();
                thread2.Join();
                thread3.Join();
                thread4.Join();
            }
            catch (Exception ex)
            {
                thread.Abort();
                thread2.Abort();
                thread3.Abort();
                thread4.Abort();
                LogSystem.Error(ex);
            }
        }

