                PriorityIsRequired = HisConfigs.Get<long>("HIS.Desktop.Plugins.SurgServiceReqExecute.RequiredPriorityOption");
                IcdCmIsRequired = HisConfigs.Get<long>("HIS.Desktop.Plugins.SurgServiceReqExecute.RequiredIcdCmOption");
