        private void InitControlState()
        {
            //IL_0003: Unknown result type (might be due to invalid IL or missing references)
            //IL_000d: Expected O, but got Unknown
            try
            {
                controlStateWorker = new ControlStateWorker();
                currentControlStateRDO = controlStateWorker.GetData("HIS.Desktop.Plugins.SurgServiceReqExecute");
                if (currentControlStateRDO == null || currentControlStateRDO.Count <= 0)
                {
                    return;
                }
                foreach (ControlStateRDO item in currentControlStateRDO)
                {
                    if (item.KEY == "spinExcuteTimeAdd" && !isEstimateDuration)
                    {
                        spinExcuteTimeAdd.Value = System.Convert.ToDecimal(item.VALUE);
                    }
                    else if (item.KEY == chkSaveGroup.Name)
                    {
                        chkSaveGroup.Checked = item.VALUE == "1";
                    }
                    if (item.KEY == chkServiceCode.Name)
                    {
                        chkServiceCode.Checked = item.VALUE == "1";
                    }
                    if (item.KEY == chkKetThuc.Name)
                    {
                        chkKetThuc.Checked = item.VALUE == "1";
                    }
                    if (item.KEY == chkSign.Name)
                    {
                        chkSign.Checked = item.VALUE == "1";
                    }
                }
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
            }
        }

