        private void SetCheckedIcdsToControl(string icdCodes, string icdNames)
        {
            try
            {
                string oldIcdNames = ((txtIcdText.Text == txtIcdText.Properties.NullValuePrompt) ? "" : txtIcdText.Text);
                txtIcdText.Text = processIcdNameChanged(oldIcdNames, icdNames);
                if (icdNames.Equals(";"))
                {
                    txtIcdText.Text = "";
                }
                if (icdCodes.Equals(";"))
                {
                    txtIcdExtraCode.Text = "";
                }
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
            }
        }

