        private void txtIcdCmSubCode_Validating(object sender, CancelEventArgs e)
        {
            try
            {
                string text = (sender as TextEdit).Text;
                text = text.Trim();
                string text2 = "";
                if (!string.IsNullOrEmpty(text))
                {
                    string text3 = ";";
                    string text4 = "";
                    string[] separator = new string[1] { text3 };
                    List<string> list = new List<string>();
                    string[] array = txtIcdCmSubCode.Text.Split(separator, StringSplitOptions.RemoveEmptyEntries);
                    if (array != null && array.Count() > 0)
                    {
                        List<HIS_ICD_CM> source = BackendDataWorker.Get<HIS_ICD_CM>();
                        string[] array2 = array;
                        foreach (string itemCode in array2)
                        {
                            HIS_ICD_CM val = source.FirstOrDefault((HIS_ICD_CM o) => o.ICD_CM_CODE.ToLower() == itemCode.ToLower());
                            if (val != null && val.ID > 0)
                            {
                                text2 = text2 + text3 + val.ICD_CM_NAME;
                                continue;
                            }
                            list.Add(itemCode);
                            text4 = text4 + text3 + itemCode;
                        }
                        text2 += text3;
                        if (!string.IsNullOrEmpty(text4))
                        {
                            MessageManager.Show(string.Format(ResourceMessage.KhongTimThayICDTuongUng, text4));
                            int start = 0;
                            int length = txtIcdCmSubCode.Text.Length - 1;
                            if (list != null && list.Count > 0)
                            {
                                start = txtIcdCmSubCode.Text.IndexOf(list[0]);
                                length = list[0].Length;
                            }
                            txtIcdCmSubCode.Focus();
                            txtIcdCmSubCode.Select(start, length);
                        }
                    }
                }
                SetCheckedIcdCmsToControl(txtIcdCmSubCode.Text, text2);
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
            }
        }

