        private void txtIcdCmSubName_KeyUp(object sender, KeyEventArgs e)
        {
            //IL_0084: Unknown result type (might be due to invalid IL or missing references)
            //IL_00a4: Expected O, but got Unknown
            //IL_009f: Unknown result type (might be due to invalid IL or missing references)
            //IL_00a5: Expected O, but got Unknown
            try
            {
                if (e.KeyCode == Keys.F1)
                {
                    Inventec.Desktop.Common.Modules.Module val = GlobalVariables.currentModuleRaws.Where((Inventec.Desktop.Common.Modules.Module o) => o.ModuleLink == "HIS.Desktop.Plugins.SecondaryIcd").FirstOrDefault();
                    if (val == null)
                    {
                        throw new NullReferenceException("Not found module by ModuleLink = 'HIS.Desktop.Plugins.SecondaryIcd'");
                    }
                    if (!val.IsPlugin || val.ExtensionInfo == null)
                    {
                        throw new NullReferenceException("Inventec.Desktop.Common.Modules.Module 'HIS.Desktop.Plugins.SecondaryIcd' is not plugins");
                    }
                    SecondaryIcdADO item = new SecondaryIcdADO(new DelegateRefeshIcdChandoanphu(GetStringIcdCms), txtIcdCmSubCode.Text, txtIcdCmSubName.Text);
                    List<object> list = new List<object>();
                    list.Add(item);
                    list.Add(true);
                    object pluginInstance = PluginInstance.GetPluginInstance(PluginInstance.GetModuleWithWorkingRoom(val, this.Module.RoomId, this.Module.RoomTypeId), list);
                    if (pluginInstance == null)
                    {
                        throw new ArgumentNullException("Khoi tao moduleData that bai. extenceInstance = null");
                    }
                    ((Form)pluginInstance).Show((IWin32Window)this);
                }
            }
            catch (Exception ex)
            {
