                if (val == null)
                {
                    LogSystem.Error("khong tim thay moduleLink = HIS.Desktop.Plugins.AssignPrescriptionYHCT");
                }
                if (val.IsPlugin && val.ExtensionInfo != null)
                {
                    List<object> list = new List<object>();
                    Inventec.Desktop.Common.Modules.Module val2 = new Inventec.Desktop.Common.Modules.Module();
                    long valueOrDefault = Inventec.Common.DateTime.Convert.SystemDateTimeToTimeNumber((DateTime?)DateTime.Now).GetValueOrDefault();
                    Mapper.CreateMap<V_HIS_SERE_SERV_5, V_HIS_SERE_SERV>();
                    V_HIS_SERE_SERV val3 = Mapper.Map<V_HIS_SERE_SERV_5, V_HIS_SERE_SERV>(sereServ);
                    AssignPrescriptionADO val4 = new AssignPrescriptionADO(serviceReq.TREATMENT_ID, valueOrDefault, serviceReq.ID, val3, new HIS.Desktop.ADO.AssignPrescriptionADO.DelegateProcessDataResult(LoadSereServOutKipResult));
