        private bool CheckRequiredMachine()
        {
            try
            {
                if (cboMachine.EditValue != null)
                {
                    return true;
                }
                string text = HisConfigs.Get<string>("HIS.Desktop.Plugins.SurgServiceReqExecute.RequiredMachineOption");
                if (text != "1" && text != "2" && text != "3" && text != "4")
                {
                    return true;
                }
                List<V_HIS_SERE_SERV_5> list = new List<V_HIS_SERE_SERV_5>();
                if (chkSaveGroup.Checked)
                {
                    if (text == "1" || text == "2")
                    {
                        List<V_HIS_SERE_SERV_5> list2 = sereServbyServiceReqs;
                        list = ((list2 != null) ? list2.ToList() : null) ?? new List<V_HIS_SERE_SERV_5>();
                    }
                    else if (text == "3" || text == "4")
                    {
                        List<V_HIS_SERE_SERV_5> list3 = sereServbyServiceReqs;
                        list = ((list3 != null) ? list3.Where((V_HIS_SERE_SERV_5 s) => s.PATIENT_TYPE_ID == HisConfigCFG.PatientTypeId__BHYT).ToList() : null) ?? new List<V_HIS_SERE_SERV_5>();
                    }
                }
                else if (text == "1" || text == "2")
                {
                    list.Add(sereServ);
                }
                else if ((text == "3" || text == "4") && sereServ.PATIENT_TYPE_ID == HisConfigCFG.PatientTypeId__BHYT)
                {
                    list.Add(sereServ);
                }
                foreach (V_HIS_SERE_SERV_5 service in list)
                {
                    List<HIS_SERVICE_MACHINE> source = (from o in BackendDataWorker.Get<HIS_SERVICE_MACHINE>()
                                                        where o.SERVICE_ID == service.SERVICE_ID
                                                        select o).ToList();
                    List<HIS_MACHINE> listMachine = (from o in BackendDataWorker.Get<HIS_MACHINE>()
                                                     where o.IS_ACTIVE == 1 && o.ROOM_IDS != null && o.ROOM_IDS.Contains(this.Module.RoomId.ToString())
                                                     select o).ToList();
                    if (!source.Any((HIS_SERVICE_MACHINE sm) => listMachine.Any((HIS_MACHINE m) => m.ID == sm.MACHINE_ID)))
                    {
                        continue;
                    }
                    string tDL_SERVICE_NAME = service.TDL_SERVICE_NAME;
                    string text2 = "Dịch vụ " + tDL_SERVICE_NAME + " chưa có thông tin máy cận lâm sàng.";
                    if (text == "1" || text == "3")
                    {
                        if (XtraMessageBox.Show(text2 + " Bạn có muốn tiếp tục không?", "Thông báo", MessageBoxButtons.YesNo, MessageBoxIcon.Exclamation) == DialogResult.No)
                        {
                            return false;
                        }
                    }
                    else if (text == "2" || text == "4")
                    {
                        XtraMessageBox.Show(text2, "Thông báo", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
                        return false;
                    }
                }
            }
            catch (Exception ex)
            {
                LogSystem.Error(ex);
            }
            return true;
        }

