        private async void SetIcdFromServiceReq(V_HIS_SERVICE_REQ data)
        {
            try
            {
                FillDataToCboIcd(txtIcdCode1, txtIcd1, cboIcd1, chkIcd1, data.ICD_CODE, serviceReq.ICD_NAME);
                FillDataToCboIcd(txtIcdCode2, txtIcd2, cboIcd2, chkIcd2, data.ICD_CODE, serviceReq.ICD_NAME);
                FillDataToCboIcd(txtIcdCode3, txtIcd3, cboIcd3, chkIcd3, data.ICD_CODE, serviceReq.ICD_NAME);
                if (!string.IsNullOrEmpty(data.ICD_SUB_CODE))
                {
                    txtIcdExtraCode.Text = data.ICD_SUB_CODE;
                }
                if (!string.IsNullOrEmpty(data.ICD_TEXT))
                {
                    txtIcdText.Text = data.ICD_TEXT;
                }
            }
            catch (Exception ex)
            {
                Exception ex2 = ex;
                LogSystem.Warn(ex2);
            }
        }

        private void CallBackLoadSereServLast()
        {
            try
            {
                if (sereServLasts != null && sereServLasts.Count > 0 && ((Control)this).InvokeRequired)
                {
                    ((Control)this).Invoke((System.Delegate)(MethodInvoker)delegate
                    {
                        gridControlSereServLast.DataSource = sereServLasts;
                    });
                }
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
            }
        }

        private void SetDataControlBySereServPttt()
        {
            try
            {
                if (sereServPTTT != null)
                {
                    txtMethodCode.Text = sereServPTTT.PTTT_METHOD_CODE;
                    cboMethod.EditValue = sereServPTTT.PTTT_METHOD_ID;
                    txtPtttGroupCode.Text = sereServPTTT.PTTT_GROUP_CODE;
                    cbbPtttGroup.EditValue = sereServPTTT.PTTT_GROUP_ID;
                    if (dataEmotionlessMethod.Exists((HIS_EMOTIONLESS_METHOD o) => o.ID == sereServPTTT.EMOTIONLESS_METHOD_ID))
                    {
                        cbbEmotionlessMethod.EditValue = sereServPTTT.EMOTIONLESS_METHOD_ID;
                    }
                    else
                    {
                        cbbEmotionlessMethod.EditValue = null;
                    }
                    txtBlood.Text = Patient.BLOOD_ABO_CODE ?? sereServPTTT.BLOOD_ABO_CODE ?? "";
                    HIS_BLOOD_ABO val = dataBloodAbo.FirstOrDefault((HIS_BLOOD_ABO o) => o.BLOOD_ABO_CODE == (Patient.BLOOD_ABO_CODE ?? sereServPTTT.BLOOD_ABO_CODE ?? ""));
                    if (val != null)
                    {
                        cbbBlood.EditValue = val.ID;
                    }
                    else
                    {
                        cbbBlood.EditValue = null;
                    }
                    txtBloodRh.Text = Patient.BLOOD_RH_CODE ?? sereServPTTT.BLOOD_RH_CODE ?? "";
                    HIS_BLOOD_RH val2 = dataBloodRh.FirstOrDefault((HIS_BLOOD_RH o) => o.BLOOD_RH_CODE == (Patient.BLOOD_RH_CODE ?? sereServPTTT.BLOOD_RH_CODE ?? ""));
                    if (val2 != null)
                    {
                        cbbBloodRh.EditValue = val2.ID;
                    }
                    else
                    {
                        cbbBloodRh.EditValue = null;
                    }
                    txtCondition.Text = sereServPTTT.PTTT_CONDITION_CODE;
                    cboCondition.EditValue = sereServPTTT.PTTT_CONDITION_ID;
                    txtCatastrophe.Text = sereServPTTT.PTTT_CATASTROPHE_CODE;
                    cboCatastrophe.EditValue = sereServPTTT.PTTT_CATASTROPHE_ID;
                    txtDeathSurg.Text = sereServPTTT.DEATH_WITHIN_CODE;
                    cboDeathSurg.EditValue = sereServPTTT.DEATH_WITHIN_ID;
                }
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
            }
        }

        private void SetDefaultCboPTTTGroup(V_HIS_SERE_SERV_5 sereServ)
        {
            try
            {
                if (sereServ == null || cbbPtttGroup.EditValue != null)
                {
                    return;
                }
                cbbPtttGroup.Enabled = true;
                txtPtttGroupCode.Enabled = true;
                if (!sereServ.EKIP_ID.HasValue)
                {
                    long num = 0L;
                    long num2 = 0L;
                    V_HIS_SERVICE surgMisuService = lstService.FirstOrDefault((V_HIS_SERVICE o) => o.ID == sereServ.SERVICE_ID);
                    if (surgMisuService != null)
                    {
                        if (surgMisuService.PTTT_GROUP_ID.HasValue)
                        {
                            HIS_PTTT_GROUP val = BackendDataWorker.Get<HIS_PTTT_GROUP>().FirstOrDefault((HIS_PTTT_GROUP o) => o.ID == surgMisuService.PTTT_GROUP_ID);
                            num = val.ID;
                            txtPtttGroupCode.Text = val.PTTT_GROUP_CODE;
                        }
                        if (surgMisuService.PTTT_METHOD_ID.HasValue)
                        {
                            HIS_PTTT_METHOD val2 = BackendDataWorker.Get<HIS_PTTT_METHOD>().FirstOrDefault((HIS_PTTT_METHOD o) => o.ID == surgMisuService.PTTT_METHOD_ID);
                            num2 = val2.ID;
                            txtMethodCode.Text = val2.PTTT_METHOD_CODE;
                        }
                    }
                    if (num2 > 0)
                    {
                        cboMethod.EditValue = num2;
                    }
                    if (num > 0)
                    {
                        cbbPtttGroup.EditValue = num;
                        if (HisConfigKeys.CheckPermissonOption == "2" && serviceReq.SERVICE_REQ_TYPE_ID == 10)
                        {
                            cbbPtttGroup.Enabled = true;
                            txtPtttGroupCode.Enabled = true;
                        }
                        else
                        {
                            cbbPtttGroup.Enabled = false;
                            txtPtttGroupCode.Enabled = false;
                        }
                    }
                }
                else
                {
                    if (hisSereServPttt == null)
                    {
                        return;
                    }
                    V_HIS_SERVICE surgService = lstService.FirstOrDefault((V_HIS_SERVICE o) => o.ID == sereServ.SERVICE_ID);
                    if (surgService != null && surgService.PTTT_GROUP_ID.HasValue)
                    {
                        HIS_PTTT_GROUP val3 = BackendDataWorker.Get<HIS_PTTT_GROUP>().FirstOrDefault((HIS_PTTT_GROUP o) => o.ID == surgService.PTTT_GROUP_ID);
                        cbbPtttGroup.EditValue = val3.ID;
                        txtPtttGroupCode.Text = val3.PTTT_GROUP_CODE;
                        cbbPtttGroup.Enabled = false;
                        txtPtttGroupCode.Enabled = false;
                    }
                }
