                    if (cboLoaiPT.EditValue != null)
                    {
                        val.PTTT_PRIORITY_ID = (long)cboLoaiPT.EditValue;
                    }
                    if (cboPhuongPhap2.EditValue != null)
                    {
                        val.EMOTIONLESS_METHOD_SECOND_ID = (long)cboPhuongPhap2.EditValue;
                    }
                    if (cboKQVoCam.EditValue != null)
                    {
                        val.EMOTIONLESS_RESULT_ID = (long)cboKQVoCam.EditValue;
                    }
                    if (cboMoKTCao.EditValue != null)
                    {
                        val.PTTT_HIGH_TECH_ID = (long)cboMoKTCao.EditValue;
                    }
                    if (cboBanMo.EditValue != null)
                    {
                        val.PTTT_TABLE_ID = (long)cboBanMo.EditValue;
                    }
                    val.NOTE = txtResultNote.Text.Trim();
                    val.CONCLUDE = txtConclude.Text.Trim();
                    val.DESCRIPTION = txtDescription.Text.Trim();
                }
            }
            catch (Exception ex)
            {
                val = null;
                LogSystem.Error(ex);
            }
            return val;
        }

        private void FillDataToControlFromTemp(HIS_SERE_SERV_PTTT_TEMP fillData)
