                    if (!string.IsNullOrEmpty(Patient.BLOOD_ABO_CODE))
                    {
                        HIS_BLOOD_ABO val = dataBloodAbo.FirstOrDefault((HIS_BLOOD_ABO o) => o.BLOOD_ABO_CODE == Patient.BLOOD_ABO_CODE);
                        if (val != null)
                        {
                            cbbBlood.EditValue = val.ID;
                            txtBlood.Text = val.BLOOD_ABO_CODE;
                        }
                        else
                        {
                            cbbBlood.EditValue = null;
                            txtBlood.Text = null;
                        }
                    }
                    else
                    {
                        cbbBlood.EditValue = fillData.BLOOD_ABO_ID;
                    }
                    if (!string.IsNullOrEmpty(Patient.BLOOD_RH_CODE))
