        public async void ValidateControl()
        {
            try
            {
                LogSystem.Debug("ValidateControl");
                if (HisConfigCFG.REQUIRED_GROUPPTTT_OPTION != "1")
                {
                    sereServ = (V_HIS_SERE_SERV_5)grdViewService.GetFocusedRow();
                    V_HIS_SERE_SERV_5 obj = sereServ;
                    LogSystem.Debug("sereServValidate " + ((obj != null) ? ((object)obj).ToString() : null));
                    if (sereServ != null)
                    {
                        V_HIS_SERVICE surgMisuService = lstService.FirstOrDefault((V_HIS_SERVICE o) => o.ID == sereServ.SERVICE_ID);
                        if (surgMisuService != null && surgMisuService != null && surgMisuService.PTTT_GROUP_ID.HasValue)
                        {
                            ValidationLookUpWithTextEdit(cbbPtttGroup, txtPtttGroupCode);
                        }
                    }
                }
                else
                {
                    ValidationLookUpWithTextEdit(cbbPtttGroup, txtPtttGroupCode);
                }
                ValidationStartTime();
                ValiVuotQuaKyTu();
                ValidationFinishTime();
                if (PriorityIsRequired == 1 || (PriorityIsRequired == 2 && serviceReq.SERVICE_REQ_TYPE_ID == 10))
                {
                    ValidationGridLookUpWithTextEdit(cboLoaiPT, txtLoaiPT);
                }
                if (MethodIsRequired == 1 || (MethodIsRequired == 2 && serviceReq.SERVICE_REQ_TYPE_ID == 10))
                {
                    ValidationGridLookUpWithTextEdit(cboMethod, txtMethodCode);
                }
                if (IcdCmIsRequired == 1)
                {
                    ValidateTextEdit(txtIcdCmCode);
                }
                ValidHeadDepartmentAndDirectorBranch();
            }
            catch (Exception ex)
            {
                Exception ex2 = ex;
                LogSystem.Warn(ex2);
            }
        }

