        private void ValidationStartTime()
        {
            try
            {
                StartTimeValidationRule startTimeValidationRule = new StartTimeValidationRule();
                startTimeValidationRule.startTime = dtStart;
                startTimeValidationRule.finishTime = dtFinish;
                startTimeValidationRule.instructionTime = serviceReq.INTRUCTION_TIME;
                startTimeValidationRule.treatmentOutTime = vhisTreatment.OUT_TIME.GetValueOrDefault();
                startTimeValidationRule.keyCheck = isAllowEditInfo;
                startTimeValidationRule.keyCheckStatsTime = HisConfigs.Get<string>("HIS.DESKTOP.PLUGINS.SURGSERVICEREQEXECUTE.BIG_START_TIME_CURRENT_TIME") == "1";
                startTimeValidationRule.ErrorType = ErrorType.Warning;
