        private void ValiVuotQuaKyTu()
        {
            try
            {
                bool isRequired = false;
                if (MannerIsRequired == 1 || (MannerIsRequired == 2 && serviceReq.SERVICE_REQ_TYPE_ID == 10))
                {
                    isRequired = true;
                }
                ValidationControlMaxLength(txtMANNER, 3000, isRequired);
                ValidationControlMaxLength(txtConclude, 1000, false);
                ValidationControlMaxLength(txtResultNote, 3000, false);
                ValidationControlMaxLength(txtDescription, 4000, false);
            }
            catch (Exception)
            {
                throw;
            }
        }

